-- 215: Original BrillaPrep WASSCE BrillaPrep transitional Sculpture beta content blueprint questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_215_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_215_guard;
INSERT INTO _migration_215_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_009' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_2' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How should a small carving block be controlled before using a mallet and chisel?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Brace it against the body while cutting away from the bench","B. Rest it on a sandbag without checking whether the block can rotate","C. Clamp it securely and keep hands outside the projected cutting path","D. Hold it with the free hand beside the intended chisel exit point"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Secure workholding makes the response to each blow predictable. The maker should also inspect handles and edges, cut in a controlled direction and keep every hand beyond the possible travel of the tool. Therefore the correct answer is C: Clamp it securely and keep hands outside the projected cutting path.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_2' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_009' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_215_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_010' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_2' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is required when applying a solvent-based sculpture coating?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Product-specific ventilation, ignition control and suitable protective equipment","B. A fan with an unprotected motor placed inside concentrated vapour","C. A dust mask used in a closed room until the odour disappears","D. Rapid heating of the coated work to shorten the drying period"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The label and safety data determine ventilation, glove and respirator requirements, storage and disposal. Flames, sparks and unsuitable electrical equipment must be controlled around flammable vapour. Therefore the correct answer is A: Product-specific ventilation, ignition control and suitable protective equipment.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_010' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_215_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_011' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_3' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the primary function of an armature in a modelled sculpture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Build the armature to the exact finished contour so only a uniformly thin skin of modelling material is required","B. Set bilateral symmetry in the framework and rely on it instead of checking proportion as volumes are added","C. Support the intended gesture and mass while modelling material is added","D. Keep the same permanent rigid metal armature inside any clay model that may later be fired"]' AND q.correct_answer IS 'C' AND q.explanation IS 'An armature is a supportive internal framework for pose, projecting parts and major proportions. Its strength, dimensions and compatibility must suit the medium and the intended final process. Therefore the correct answer is C: Support the intended gesture and mass while modelling material is added.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_011' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_215_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_012' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_3' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How should a substantial fresh mass of clay be added to an existing leather-hard area?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Attach the fresh mass with thick slip and expose the join to rapid airflow","B. Recondition the receiving area toward compatible moisture, score and slip both surfaces, compress the join, then dry the work slowly and evenly","C. Saturate the entire leather-hard form until its surface becomes slurry","D. Score the leather-hard surface and attach very wet clay without moisture adjustment"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A substantial join needs moisture compatibility as well as mechanical key. Controlled reconditioning, scoring, compatible slip and compression should be followed by support and slow, even drying to equalise shrinkage. Therefore the correct answer is B: Recondition the receiving area toward compatible moisture, score and slip both surfaces, compress the join, then dry the work slowly and evenly.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_012' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_009', 'topic_was_sculpture_b004_2', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'How should a small carving block be controlled before using a mallet and chisel?', 'multiple_choice', NULL, '["A. Brace it against the body while cutting away from the bench","B. Rest it on a sandbag without checking whether the block can rotate","C. Clamp it securely and keep hands outside the projected cutting path","D. Hold it with the free hand beside the intended chisel exit point"]', 'C', 'Secure workholding makes the response to each blow predictable. The maker should also inspect handles and edges, cut in a controlled direction and keep every hand beyond the possible travel of the tool. Therefore the correct answer is C: Clamp it securely and keep hands outside the projected cutting path.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_2', 'Explain', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_010', 'topic_was_sculpture_b004_2', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'What is required when applying a solvent-based sculpture coating?', 'multiple_choice', NULL, '["A. Product-specific ventilation, ignition control and suitable protective equipment","B. A fan with an unprotected motor placed inside concentrated vapour","C. A dust mask used in a closed room until the odour disappears","D. Rapid heating of the coated work to shorten the drying period"]', 'A', 'The label and safety data determine ventilation, glove and respirator requirements, storage and disposal. Flames, sparks and unsuitable electrical equipment must be controlled around flammable vapour. Therefore the correct answer is A: Product-specific ventilation, ignition control and suitable protective equipment.', 'easy', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_2', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_011', 'topic_was_sculpture_b004_3', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'What is the primary function of an armature in a modelled sculpture?', 'multiple_choice', NULL, '["A. Build the armature to the exact finished contour so only a uniformly thin skin of modelling material is required","B. Set bilateral symmetry in the framework and rely on it instead of checking proportion as volumes are added","C. Support the intended gesture and mass while modelling material is added","D. Keep the same permanent rigid metal armature inside any clay model that may later be fired"]', 'C', 'An armature is a supportive internal framework for pose, projecting parts and major proportions. Its strength, dimensions and compatibility must suit the medium and the intended final process. Therefore the correct answer is C: Support the intended gesture and mass while modelling material is added.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_3', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_012', 'topic_was_sculpture_b004_3', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'How should a substantial fresh mass of clay be added to an existing leather-hard area?', 'multiple_choice', NULL, '["A. Attach the fresh mass with thick slip and expose the join to rapid airflow","B. Recondition the receiving area toward compatible moisture, score and slip both surfaces, compress the join, then dry the work slowly and evenly","C. Saturate the entire leather-hard form until its surface becomes slurry","D. Score the leather-hard surface and attach very wet clay without moisture adjustment"]', 'B', 'A substantial join needs moisture compatibility as well as mechanical key. Controlled reconditioning, scoring, compatible slip and compression should be followed by support and slow, even drying to equalise shrinkage. Therefore the correct answer is B: Recondition the receiving area toward compatible moisture, score and slip both surfaces, compress the join, then dry the work slowly and evenly.', 'hard', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_3', 'Explain', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_sculpture_b004_009', 'q_was_sculpture_b004_010', 'q_was_sculpture_b004_011', 'q_was_sculpture_b004_012');
